(1172962, 147595, 30861, '<td valign="top">Va VOOM. I don''t knjow how well this will do, but the schizophrenia of the 2 sides is stunning. Very strong entry.</td>', 'Va VOOM. I don''t knjow how well this will do, but the schizophrenia of the 2 sides is stunning. Very strong entry.', '2005-02-16 02:05:27.000000', NULL, 1),
(1172963, 147507, 31637, '<td valign="top">where have I seen this bridge before?? (joking)..nice job here...good color</td>', 'where have I seen this bridge before?? (joking)..nice job here...good color', '2005-02-16 02:06:06.000000', NULL, 1),
(1172964, 145410, 30861, '<td valign="top">That''s an astonishing shadow! Very nice shot.</td>', 'That''s an astonishing shadow! Very nice shot.', '2005-02-16 02:06:13.000000', NULL, 1),
(1172966, 146818, 8284, '<td valign="top">Title fits well, but this needs work.  Partial desaturation doesn''t work well - try going full B&amp;W.  Nothing is in focus.  Sky is just blown out &amp; doesn''t add to the feel of the shot.</td>', 'Title fits well, but this needs work.  Partial desaturation doesn''t work well - try going full B&W.  Nothing is in focus.  Sky is just blown out & doesn''t add to the feel of the shot.', '2005-02-16 02:07:06.000000', NULL, 1),
(1172968, 145900, 31047, '<td valign="top">to much oof.</td>', 'to much oof.', '2005-02-16 02:07:46.000000', NULL, 1),
(1172971, 146208, 8284, '<td valign="top">I get the feeling this would look better in color.  Seems a little over-sharpened?  I like the composition.  Would like to see another attempt.  RE: the title.  Do they have Bank of America in Rome?</td>', 'I get the feeling this would look better in color.  Seems a little over-sharpened?  I like the composition.  Would like to see another attempt.  RE: the title.  Do they have Bank of America in Rome?', '2005-02-16 02:09:43.000000', NULL, 1),
(1172976, 147538, 8284, '<td valign="top">Title doesn''t fit.  This bridge doesn''t go into the distance.  Rotation is too strong.  I like that you can see thru the water, and the reflections are caught well.</td>', 'Title doesn''t fit.  This bridge doesn''t go into the distance.  Rotation is too strong.  I like that you can see thru the water, and the reflections are caught well.', '2005-02-16 02:12:12.000000', NULL, 1),
(1172977, 146640, 31637, '<td valign="top">congratulations on your ribbon... :)</td>', 'congratulations on your ribbon... :)', '2005-02-16 02:12:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
