(1174841, 147592, 32792, '<td valign="top">If only this was a member challenge, u could have cloned out that sprayed wall!</td>', 'If only this was a member challenge, u could have cloned out that sprayed wall!', '2005-02-16 14:18:32.000000', NULL, 1),
(1174842, 147219, 25735, '<td valign="top">very good composition</td>', 'very good composition', '2005-02-16 14:18:32.000000', NULL, 1),
(1174843, 147632, 29256, '<td valign="top">Maybe changing the DOF would help along with a different light setting. The bridge is just too dark but cries out to show it''s detail.</td>', 'Maybe changing the DOF would help along with a different light setting. The bridge is just too dark but cries out to show it''s detail.', '2005-02-16 14:18:44.000000', NULL, 1),
