(1179437, 146862, 25024, '<td valign="top">Nice idea and well lit and taken</td>', 'Nice idea and well lit and taken', '2005-02-18 06:10:16.000000', NULL, 1),
(1179439, 146954, 31046, '<td valign="top">Very nice one, although I would prefer the entire bridge to be in the photo</td>', 'Very nice one, although I would prefer the entire bridge to be in the photo', '2005-02-18 06:10:35.000000', NULL, 1),
(1179441, 145241, 31046, '<td valign="top">Excellent quality, good composition</td>', 'Excellent quality, good composition', '2005-02-18 06:12:30.000000', NULL, 1),
