(1180095, 146440, 24212, '<td valign="top">A good subject for black and white treatment, although I''d prefer to see a little more texture in the sky.</td>', 'A good subject for black and white treatment, although I''d prefer to see a little more texture in the sky.', '2005-02-18 13:52:24.000000', NULL, 1),
(1180100, 146430, 24212, '<td valign="top">I think that this would work even better without the cyclist. Great symmetrical shot.</td>', 'I think that this would work even better without the cyclist. Great symmetrical shot.', '2005-02-18 13:54:20.000000', NULL, 1),
(1180102, 147178, 30222, '<td valign="top">great dramatics<br/>splendid composition though the bushy tree in the foreground is not needed in the lovely emptyness <br/>u prob had no choice i guess</td>', 'great dramaticssplendid composition though the bushy tree in the foreground is not needed in the lovely emptyness u prob had no choice i guess', '2005-02-18 13:54:46.000000', NULL, 1),
