(1180400, 147311, 19333, '<td valign="top">Being the image in the middle grays, the black thick border''s too prominent. nice otherwise</td>', 'Being the image in the middle grays, the black thick border''s too prominent. nice otherwise', '2005-02-18 16:19:22.000000', NULL, 1),
(1180401, 147442, 30214, '<td valign="top">wow, great lighting against a threatening sky. One of my favorites here</td>', 'wow, great lighting against a threatening sky. One of my favorites here', '2005-02-18 16:19:36.000000', NULL, 1),
