INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1181151, 147626, 27178, '<td valign="top">Wonderful idea for the challenge and I love the blue - very striking and appealing.</td>', 'Wonderful idea for the challenge and I love the blue - very striking and appealing.', '2005-02-18 21:20:53.000000', NULL, 1),
(1181152, 145822, 11895, '<td valign="top">very good depth of field, a little noisy in the sky, leaves me wondering what a color version would have looked like</td>', 'very good depth of field, a little noisy in the sky, leaves me wondering what a color version would have looked like', '2005-02-18 21:21:04.000000', NULL, 1),
(1181155, 147178, 27178, '<td valign="top">nicely framed and I love how the bridge disappears into the fog.</td>', 'nicely framed and I love how the bridge disappears into the fog.', '2005-02-18 21:22:00.000000', NULL, 1),
(1181157, 145592, 27178, '<td valign="top">very dramatic with the fog and the lighting. Excellent POV too!</td>', 'very dramatic with the fog and the lighting. Excellent POV too!', '2005-02-18 21:23:02.000000', NULL, 1),
(1181160, 145886, 11895, '<td valign="top">needs more depth of field</td>', 'needs more depth of field', '2005-02-18 21:24:30.000000', NULL, 1),
(1181161, 147503, 27178, '<td valign="top">What an excellent guitar - it''s loud even as a photograph! :-)<br/> <br/>I really like the framing and POV - the black BG was a good idea too. Well done.</td>', 'What an excellent guitar - it''s loud even as a photograph! :-) I really like the framing and POV - the black BG was a good idea too. Well done.', '2005-02-18 21:26:28.000000', NULL, 1),
(1181165, 146913, 27178, '<td valign="top">I can''t decide if I like the lighting or not, but the framing and composition are wonderful. Great idea for the challenge.</td>', 'I can''t decide if I like the lighting or not, but the framing and composition are wonderful. Great idea for the challenge.', '2005-02-18 21:28:36.000000', NULL, 1),
(1181168, 147464, 27178, '<td valign="top">This is probably the funest interpretation of the challenge :-)</td>', 'This is probably the funest interpretation of the challenge :-)', '2005-02-18 21:29:31.000000', NULL, 1),
(1181172, 145786, 27178, '<td valign="top">For me the only thing that takes away from this image somewhat is the lighting - I would have liked to see it a little warmer and without the harsh reflections (IMHO). Wonderful idea for the challenge.</td>', 'For me the only thing that takes away from this image somewhat is the lighting - I would have liked to see it a little warmer and without the harsh reflections (IMHO). Wonderful idea for the challenge.', '2005-02-18 21:33:07.000000', NULL, 1),
(1181175, 145651, 27178, '<td valign="top">Love the tones in this photograph and the way it is framed. Excellent POV.</td>', 'Love the tones in this photograph and the way it is framed. Excellent POV.', '2005-02-18 21:38:03.000000', NULL, 1),
(1181183, 147620, 27178, '<td valign="top">While I love your interpretation of the challenge I''m not sure I like the B/W mostly because of the flowers (?) that look like white dots. This would have looked really cool in sepia - to complement the dates on the headstones IMO.</td>', 'While I love your interpretation of the challenge I''m not sure I like the B/W mostly because of the flowers (?) that look like white dots. This would have looked really cool in sepia - to complement the dates on the headstones IMO.', '2005-02-18 21:42:00.000000', NULL, 1),
(1181187, 146817, 27178, '<td valign="top">wonderful composition - I like how everything converges to a point.</td>', 'wonderful composition - I like how everything converges to a point.', '2005-02-18 21:45:18.000000', NULL, 1),
(1181192, 145672, 27178, '<td valign="top">Sweet long exposure shot - I love the saturated colors!</td>', 'Sweet long exposure shot - I love the saturated colors!', '2005-02-18 21:47:29.000000', NULL, 1),
(1181196, 146362, 27178, '<td valign="top">Wonderful composition and tones. I like your interpretation of the challenge also.</td>', 'Wonderful composition and tones. I like your interpretation of the challenge also.', '2005-02-18 21:48:54.000000', NULL, 1),
