INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2624801, 147538, 50695, '<td valign="top">it just amazes me how such a wonderful shot could get such a low score. I suppose it''s fairly programmatic: soft focus = bad. blown out areas = bad. I wish people would rise up from their programs and see anew.</td>', 'it just amazes me how such a wonderful shot could get such a low score. I suppose it''s fairly programmatic: soft focus = bad. blown out areas = bad. I wish people would rise up from their programs and see anew.', '2006-07-15 14:57:52.000000', NULL, 0),
(2624819, 147538, 60799, '<td valign="top">Cool shot!  I really like your varied areas of exposure.  There are lines that keep your attention moving all over the picture.  This shot really takes me back to being a kid, playin in the river underneath the bridge, fishing or catching crawfish... Thanks.</td>', 'Cool shot!  I really like your varied areas of exposure.  There are lines that keep your attention moving all over the picture.  This shot really takes me back to being a kid, playin in the river underneath the bridge, fishing or catching crawfish... Thanks.', '2006-07-15 15:22:06.000000', NULL, 0),
(2649105, 147604, 58785, '<td valign="top">This is an unbelievable image... I probably could see this kind of scenes only in my dreams... Excellent photo :)</td>', 'This is an unbelievable image... I probably could see this kind of scenes only in my dreams... Excellent photo :)', '2006-07-22 16:02:32.000000', NULL, 0),
